/**
 * Checks that a change only points at records this workspace can use.
 *
 * A row that lives in another organization is refused with the same
 * tenant-scope error as any other cross-workspace access. A row that is
 * missing, archived, outside the project or issue, or not a current member
 * is not found. Callers run these checks before writing, so a refusal leaves
 * no row, field, or event behind.
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Actor } from "@/types/member";
import { NotFoundError, requireFound } from "./_support";

/** An assignee or project lead must be an active member of this workspace. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

/** Every label id must be one of this workspace's own labels. */
export async function assertLabelsInWorkspace(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  const seen = new Set<string>();
  for (const labelId of labelIds) {
    if (seen.has(labelId)) continue;
    seen.add(labelId);

    const label = requireFound(
      await labelRepo.findLabelByIdAnyOrg(labelId),
      "Label",
      labelId,
    );
    assertOrgScope(actor, label.orgId);
  }
}

/** A parent issue must be a live issue of the same project. */
export async function assertParentIssue(
  actor: Actor,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = requireFound(
    await issueRepo.findIssueByIdAnyOrg(parentId),
    "Issue",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (parent.projectId !== projectId || isArchived(parent)) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** A reply must target a live, top-level comment on the same issue. */
export async function assertReplyTarget(
  actor: Actor,
  issueId: IssueId,
  parentId: CommentId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = requireFound(
    await commentRepo.findCommentByIdAnyOrg(parentId),
    "Comment",
    parentId,
  );
  assertOrgScope(actor, parent.orgId);
  if (
    parent.issueId !== issueId ||
    parent.parentId !== null ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

