/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The composer resolves its ids from the
 * same member list the server reads here, so they are taken as they come;
 * the body scan only adds handles the composer did not catch.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);

  return [...new Set([...resolved, ...clientProvided])];
}

input.new_string:
/**
 * Union of `@handle` mentions in the body and ids the composer supplied.
 * Both sources are kept only when they name a current member of this
 * workspace. Anyone else is dropped, so they are never stored or notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    status: "active",
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const seen = new Set<UserId>(resolved);
  const mentioned: UserId[] = [...resolved];

  for (const userId of clientProvided) {
    if (seen.has(userId)) continue;
    seen.add(userId);
    const member = await memberRepo.findMember(orgId, userId);
    if (!member || member.status !== "active") continue;
    mentioned.push(userId);
  }

  return mentioned;
}

