/**
 * Temporary verification for workspace reference checks. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let northIssue: Issue;
let acmeIssue: Issue;
let otherProject: Project;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("refnorth");
  acme = await createTenant("refacme");
  northIssue = await issueService.createIssue(
    north.actors.member,
    issueInput(north.org.id, north.project.id, { title: "North root" }),
  );
  acmeIssue = await issueService.createIssue(
    acme.actors.member,
    issueInput(acme.org.id, acme.project.id, { title: "Acme root" }),
  );
  otherProject = await projectService.createProject(north.actors.member, {
    orgId: north.org.id,
    name: "Other project",
    slug: "other",
    key: "OTH",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
});

afterAll(() => {
  cleanup();
});

async function issueCount(): Promise<number> {
  return issueRepo.countIssues(north.org.id, north.project.id, {
    includeArchived: true,
  });
}

describe("reference checks", () => {
  it("hides a label that belongs to another workspace", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "acme-only",
      color: "#111111",
      description: null,
    });
    const own = await labelRepo.insertLabel({
      orgId: north.org.id,
      name: "north-own",
      color: "#222222",
      description: null,
    });
    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const seeded = await issueRepo.insertIssue(
      {
        ...issueInput(north.org.id, north.project.id, { title: "Stale labels" }),
        labelIds: [foreign.id, own.id],
      },
      north.userIds.member,
      number,
    );

    const loaded = await issueService.getIssue(
      north.actors.member,
      north.org.id,
      seeded.id,
    );
    expect(loaded.labels.map((label) => label.id)).toEqual([own.id]);
    expect(loaded.issue.labelIds).toEqual([own.id]);
    expect(loaded.labels.every((label) => label.orgId === north.org.id)).toBe(true);
  });

  it("refuses a foreign label without creating or announcing an issue", async () => {
    const foreign = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "stolen",
      color: "#333333",
      description: null,
    });
    const before = await issueCount();
    const received: unknown[] = [];
    const off = subscribe("issue.created", (payload) => received.push(payload));
    try {
      await expect(
        issueService.createIssue(north.actors.member, {
          ...issueInput(north.org.id, north.project.id, { title: "Bad labels" }),
          labelIds: [foreign.id],
        }),
      ).rejects.toBeInstanceOf(TenantScopeError);
      expect(await issueCount()).toBe(before);
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("refuses a missing label and does not change other fields", async () => {
    const issue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Keep this title" }),
    );
    const received: unknown[] = [];
    const off = subscribe("issue.updated", (payload) => received.push(payload));
    try {
      await expect(
        issueService.updateIssue(north.actors.member, {
          orgId: north.org.id,
          issueId: issue.id,
          title: "Should not stick",
          labelIds: ["01ARZ3NDEKTSV4RRFFQ69G5FAV" as never],
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      const after = await issueRepo.findIssueById(north.org.id, issue.id);
      expect(after?.title).toBe("Keep this title");
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("refuses a parent from another workspace", async () => {
    const before = await issueCount();
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "Cross parent" }),
        parentId: acmeIssue.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await issueCount()).toBe(before);
  });

  it("refuses a parent from another project or an archived parent", async () => {
    const elsewhere = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, otherProject.id, { title: "Other project issue" }),
    );
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "Wrong project parent" }),
        parentId: elsewhere.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Soon archived" }),
    );
    await issueService.archiveIssue(north.actors.member, north.org.id, archived.id);
    const before = await issueCount();
    await expect(
      issueService.createIssue(north.actors.member, {
        ...issueInput(north.org.id, north.project.id, { title: "Archived parent" }),
        parentId: archived.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await issueCount()).toBe(before);
  });

  it("accepts a live parent in the same project", async () => {
    const child = await issueService.createIssue(north.actors.member, {
      ...issueInput(north.org.id, north.project.id, { title: "Child" }),
      parentId: northIssue.id,
    });
    expect(child.parentId).toBe(northIssue.id);
  });

  it("refuses an assignee who is not a current member and does not announce", async () => {
    const received: unknown[] = [];
    const off = subscribe("issue.assigned", (payload) => received.push(payload));
    try {
      await expect(
        issueService.assignIssue(north.actors.member, {
          orgId: north.org.id,
          issueId: northIssue.id,
          assigneeId: acme.userIds.admin,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect((await issueRepo.findIssueById(north.org.id, northIssue.id))?.assigneeId).toBeNull();
      expect(received).toHaveLength(0);

      const member = await memberRepo.findMember(north.org.id, north.userIds.viewer);
      await memberRepo.archiveMember(north.org.id, member!.id);
      await expect(
        issueService.createIssue(north.actors.member, {
          ...issueInput(north.org.id, north.project.id, {
            title: "Former assignee",
            assigneeId: north.userIds.viewer,
          }),
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      off();
    }
  });

  it("refuses a project lead who is not a current member", async () => {
    const before = (await projectRepo.listProjects({
      orgId: north.org.id,
      limit: 50,
      cursor: null,
    })).total;
    const received: unknown[] = [];
    const off = subscribe("project.created", (payload) => received.push(payload));
    try {
      await expect(
        projectService.createProject(north.actors.member, {
          orgId: north.org.id,
          name: "Stranger lead",
          slug: "stranger-lead",
          key: "STR",
          description: null,
          visibility: "org",
          leadId: acme.userIds.owner,
          color: "#6366f1",
          targetDate: null,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect(received).toHaveLength(0);
      const after = await projectRepo.listProjects({
        orgId: north.org.id,
        limit: 50,
        cursor: null,
      });
      expect(after.total).toBe(before);
    } finally {
      off();
    }

    const kept = await projectRepo.findProjectById(north.org.id, otherProject.id);
    await expect(
      projectService.updateProject(north.actors.member, {
        orgId: north.org.id,
        projectId: otherProject.id,
        leadId: acme.userIds.member,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect((await projectRepo.findProjectById(north.org.id, otherProject.id))?.leadId).toBe(
      kept?.leadId ?? null,
    );
  });

  it("refuses replies that are not a live top-level comment on the same issue", async () => {
    const top = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "top",
      parentId: null,
      mentionedUserIds: [],
    });
    const reply = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: northIssue.id,
      body: "reply",
      parentId: top.id,
      mentionedUserIds: [],
    });
    const otherIssue = await issueService.createIssue(
      north.actors.member,
      issueInput(north.org.id, north.project.id, { title: "Other issue" }),
    );
    const elsewhere = await commentService.createComment(north.actors.member, {
      orgId: north.org.id,
      issueId: otherIssue.id,
      body: "elsewhere",
      parentId: null,
      mentionedUserIds: [],
    });
    const foreign = await commentService.createComment(acme.actors.member, {
      orgId: acme.org.id,
      issueId: acmeIssue.id,
      body: "foreign",
      parentId: null,
      mentionedUserIds: [],
    });

    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "to a reply",
        parentId: reply.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "wrong issue",
        parentId: elsewhere.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "other workspace",
        parentId: foreign.id,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await commentService.deleteComment(north.actors.member, {
      orgId: north.org.id,
      commentId: top.id,
    });
    const before = await commentRepo.countComments(north.org.id, northIssue.id);
    const received: unknown[] = [];
    const off = subscribe("comment.created", (payload) => received.push(payload));
    try {
      await expect(
        commentService.createComment(north.actors.member, {
          orgId: north.org.id,
          issueId: northIssue.id,
          body: "to a deleted comment",
          parentId: top.id,
          mentionedUserIds: [],
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect(await commentRepo.countComments(north.org.id, northIssue.id)).toBe(before);
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("drops mentions of anyone who is not a current member", async () => {
    const ghost = await userRepo.insertUser({
      email: "ghost@example.com",
      name: "Ghost",
      passwordHash: "seed",
    });
    const received: unknown[] = [];
    const off = subscribe("comment.created", (payload) => received.push(payload));
    try {
      const comment = await commentService.createComment(north.actors.member, {
        orgId: north.org.id,
        issueId: northIssue.id,
        body: "ping @admin and @ghost",
        parentId: null,
        mentionedUserIds: [acme.userIds.owner, north.userIds.admin, ghost.id],
      });
      expect(comment.mentionedUserIds).toEqual([north.userIds.admin]);
      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        mentionedUserIds: [north.userIds.admin],
      });
    } finally {
      off();
    }
  });
});

